// Formula quests use atom counts. Collecting a formula is a puzzle abstraction,
// not a claim that pouring pure elements together makes the substance safely.
export const SUBSTANCES=[
 {id:'salt',level:5,name:'Харчова сіль',formula:'NaCl',atoms:['Na','Cl'],benefit:'Комора: на 20% більше їжі з рейсів',science:'NaCl — формула натрій хлориду. Соління відоме з давнини; у грі відтворюємо склад речовини, а не спосіб її виготовлення.'},
 {id:'water',level:10,name:'Вода для поселення',formula:'H₂O',atoms:['H','H','O'],benefit:'Запас води: +5 до здоров’я поселення',science:'H₂O містить два атоми Гідрогену й один Оксигену. Формула не означає, що вода питна: для цього потрібні очищення й контроль якості.'},
 {id:'greenhouse',level:15,name:'Вуглекислий газ',formula:'CO₂',atoms:['C','O','O'],benefit:'Теплиці: ще +20% їжі з полів',science:'CO₂ бере участь у фотосинтезі. Збагачення повітря теплиць потребує контрольованих умов. Бонус урожаю — ігрове спрощення.'},
 {id:'ammonia',level:20,name:'Аміак',formula:'NH₃',atoms:['N','H','H','H'],benefit:'Добрива: ще +30% їжі з полів',science:'N₂ + 3H₂ ⇌ 2NH₃. Промисловий процес Габера—Боша потребує спеціальних умов і каталізатора. Тут збирається лише склад молекули.'},
 {id:'glass',level:25,name:'Основа скла',formula:'SiO₂',atoms:['Si','O','O'],benefit:'Лабораторне скло: +1 дослідження за нову перемогу',science:'SiO₂ — силіцій діоксид, основний компонент звичайного скла. Виробництво скла також потребує інших компонентів і високої температури.'}
];
export function missionsFor(level,discovered){const pool=SUBSTANCES.filter(q=>q.level<=level&&q.atoms.every(s=>discovered.includes(s)));if(!pool.length)return [];const n=Math.min(pool.length,level>=40?3:level>=20?2:1),offset=Math.floor(level/5)%pool.length;return Array.from({length:n},(_,i)=>pool[(offset+i)%pool.length]);}
export function formulaMatches(tube,quest){return tube.length===quest.atoms.length&&quest.atoms.every(s=>tube.filter(x=>x===s).length===quest.atoms.filter(x=>x===s).length);}
export function formulaMove(t,a,b,quest){if(a===b||a===0||!t[a]?.length||!t[b]||t[b].length>=4)return null;const s=t[a].at(-1);if(b===0){if(t[0].filter(x=>x===s).length>=quest.atoms.filter(x=>x===s).length)return null;const next=t.map(x=>[...x]);next[0].push(next[a].pop());return next;}if(t[b].length&&t[b].at(-1)!==s)return null;const next=t.map(x=>[...x]);let n=0;for(let i=t[a].length-1;i>=0&&t[a][i]===s;i--)n++;n=Math.min(n,4-t[b].length);next[b].push(...next[a].splice(-n));return next;}
export function createMission(quest,level,discovered){const blockers=discovered.filter(s=>!quest.atoms.includes(s));const count=Math.min(blockers.length,level>=30?2:1),tubes=Array.from({length:7},()=>[]);for(let i=0;i<count;i++){tubes[1+i*2]=[blockers[i],blockers[i]];tubes[2+i*2]=[blockers[i],blockers[i]];}const shift=level%4;quest.atoms.forEach((s,i)=>tubes[1+(i+shift)%4].push(s));return {tubes,moves:quest.atoms.length+count+Math.max(2,7-Math.floor(level/10))};}
export function settleMission(t,quest,claimed=false){const tubes=t.map(x=>[...x]);const formula=!claimed&&formulaMatches(tubes[0],quest);if(formula)tubes[0]=[];const completed=[];for(let i=1;i<tubes.length;i++)if(tubes[i].length===4&&tubes[i].every(s=>s===tubes[i][0])){completed.push({index:i,symbol:tubes[i][0]});tubes[i]=[];}return {tubes,formula,completed,done:(claimed||formula)&&tubes.every(x=>!x.length)};}
